/* HELL_ARENA_HEARTH_BEGIN */
(() => {
  const pyreX = 35, pyreZ = 52;
  const isArenaPyre = spec => spec.x === pyreX && spec.z === pyreZ;
  const nativePyre = di.pyre.build;
  di.pyre.build = function (box, cylinder, spec) {
    // Native placement, collision footprint, ember emitter and map behavior are
    // retained by the decoration record. Its visible parts are batched below.
    if (T.level !== 0 || !isArenaPyre(spec)) return nativePyre.apply(this, arguments);
  };

  const texels=/* HEARTH_TEXELS_BEGIN */ {
    clinker: "",
    iron: "",
    copper: "",
    coal: "",
    bed: "",
    ashlar: "",
    gold: "",
    seam: ""
  } /* HEARTH_TEXELS_END */;
  const tiles = Object.keys(texels);
  const fract = n => n - Math.floor(n);
  const grain = (x, y, salt = 0) => fract(Math.sin(x * 27.15 + y * 81.32 + salt * 117.13) * 14374.852);
  const clamp = (n, min = 0, max = 1) => Math.max(min, Math.min(max, n));
  function hearthAtlas() {
    const atlas = Z(e0(ctx => {
      const pixels = ctx.createImageData(256, 144);
      tiles.forEach((tile, index) => {
        const originX = index % 4 * 64, originY = (index / 4 | 0) * 72;
        const raw = atob(texels[tile]);
        for (let y = 0; y < 72; y++) for (let x = 0; x < 64; x++) {
          const u = clamp(x - 2, 0, 59), v = clamp(y - 2, 0, 67);
          const source = (v * 60 + u) * 2;
          const sample = raw.charCodeAt(source) | raw.charCodeAt(source + 1) << 8;
          const i = ((originY + y) * 256 + originX + x) * 4;
          const noise = 2.5 * (grain(u,v,index) - .5);
          pixels.data[i] = (sample >> 11) * 255/31 + noise;
          pixels.data[i+1] = (sample >> 5 & 63) * 255/63 + noise;
          pixels.data[i+2] = (sample & 31) * 255/31 + noise;
          pixels.data[i + 3] = 255;
        }
      });
      ctx.putImageData(pixels, 0, 0);
    }, 256, 144));
    atlas.name = "hellHearthTiles";
    atlas.colorSpace = ha;
    atlas.minFilter = YC;
    atlas.generateMipmaps = true;
    return atlas;
  }

  function buildHearth(floor, scene, x, z) {
    const groups = new Map();
    const tileMaterial = Z(new $e({map:hearthAtlas(), vertexColors:true, toneMapped:false, side:hi}));
    const roomAngle = Math.PI / 8;
    const angles = Array.from({length:8}, (_, i) => roomAngle + i * Math.PI / 4);
    const vertices = [], UVs = [], swatches = [];
    const point = (radius, y, angle) => [Math.sin(angle) * radius, y, Math.cos(angle) * radius];
    function polygon(tile, a, b, c, d, brightness=1) {
      const index = tiles.indexOf(tile), texX = index % 4 * 64, texY = (index / 4 | 0) * 72;
      const x0 = (texX + 2.5) / 256, y0 = (texY + 2.5) / 144;
      const width = 59 / 256, height = 67 / 144;
      for (const [p, u, v] of [[a,0,0],[b,0,1],[c,1,1],[a,0,0],[c,1,1],[d,1,0]]) {
        vertices.push(...p); UVs.push(x0 + u * width, 1 - y0 - (1-v) * height);
        swatches.push(brightness, brightness * .95, brightness * .87);
      }
    }
    function band(tile, lowerRadius, upperRadius, lowerY, upperY, light=1, split=0) {
      for (let i = 0; i < angles.length; i++) {
        const start = angles[i] + split, end = angles[i] + Math.PI / 4 - split;
        const shade = .84 + .15 * Math.sin((start + end) * .5 + .48) + .07 * (i % 3);
        polygon(tile, point(lowerRadius,lowerY,start), point(upperRadius,upperY,start),
          point(upperRadius,upperY,end), point(lowerRadius,lowerY,end), shade * light);
      }
    }
    function slab(tile, a, b, left, right, y, wear=1) {
      polygon(tile, point(a,y,left),point(b,y,left),point(b,y,right),point(a,y,right),wear);
    }
    function detail(tile, geo, matrix, brightness=1) {
      const index = tiles.indexOf(tile), u = geo.getAttribute("uv");
      const texX = index % 4 * 64, texY = (index / 4 | 0) * 72;
      for (let i = 0; i < u.count; i++) u.setXY(i, (texX + 2.5 + u.getX(i) * 59) / 256,
        1 - (texY + 2.5 + (1 - u.getY(i)) * 67) / 144);
      Yd(groups, tileMaterial, geo, matrix);
      const part = groups.get(tileMaterial).at(-1);
      const color = new Float32Array(part.getAttribute("position").count * 3);
      const normal = part.getAttribute("normal");
      for (let i = 0; i < normal.count; i++) {
        const shade = (.66 + Math.max(0, normal.getY(i)) * .27 + Math.abs(normal.getZ(i)) * .10) * brightness;
        color[i*3] = shade; color[i*3+1] = shade * .96; color[i*3+2] = shade * .89;
      }
      part.setAttribute("color", new y0(color,3));
    }
    function box(tile, w, h, d, x, y, z, pitch=0, yaw=0, roll=0, brightness=1) {
      detail(tile, new Ne(w,h,d), E(x,y,z,pitch,yaw,roll), brightness);
    }
    const vertical = new Y(0,1,0), unitScale = new Y(1,1,1);
    function along(x,y,z,axis) {
      return new fe().compose(new Y(x,y,z),new Pn().setFromUnitVectors(vertical,axis),unitScale);
    }

    // Footing, ash vent and shallow cast bowl. The stone lands within the
    // pyre's original solid footprint. Only the rim overhangs the footing.
    band("seam", .79, .79, 0, .035, .72);
    band("clinker", .78, .78, .035, .136, 1.12, .012);
    band("ashlar", .78, .68, .136, .195, 1.10, .005);
    band("seam", .677, .685, .195, .589, .80);
    band("clinker", .683, .692, .195, .589, 1.19, .008);
    band("copper", .696, .715, .591, .620, 1.45, .004);
    band("iron", .715, .748, .620, .724, 1.34, .006);
    band("ashlar", .748, .741, .724, .745, 1.35);
    band("copper", .741, .627, .745, .759, 1.16);
    band("coal", .617, .627, .565, .759, .89);
    for(let i = 0; i < angles.length; i++) {
      const angle = angles[i] + Math.PI / 8;
      const x0 = Math.sin(angle), z0 = Math.cos(angle);
      for(const [dx, height, width] of [[-.083,.132,.022],[-.021,.168,.026],[.071,.103,.018]]) {
        const sx=x0*.645+Math.cos(angle)*dx, sz=z0*.645-Math.sin(angle)*dx;
        box("iron",width+.023,height+.018,.015,sx,.358,sz,0,angle,0,.86);
        box("seam",width,height,.021,sx,.359,sz,0,angle,0,.54);
        if(i%3!==0)box("bed",width*.66,.024,.024,sx,.373-height*.49,sz,0,angle,0,.69);
      }
      // The copper shoulders are tied to each side of the octagon by rivets.
      for(const dx of [-.164,.163]) {
        const sx=x0*.663+Math.cos(angle)*dx, sz=z0*.663-Math.sin(angle)*dx;
        detail("gold",new Eo(.015,.021,.025,5),along(sx,.608,sz,new Y(x0,0,z0)),1.47);
      }
    }

    // The grate has cinder pockets, curved burned wood and thin lines of age.
    detail("bed",new Eo(.571,.547,.044,8),E(0,.716,0,0,roomAngle),1.41);
    for (const [length, radius, angle, x0, z0, lift, rise] of [
      [.83,.114,.25,.20,-.14,.815,-.04], [.73,.108,1.27,-.148,.10,.835,-.20],
      [.97,.131,2.04,-.045,-.085,.956,.40],[.62,.114,1.0,.04,.20,.885,.20]
    ]) {
      const axis = new Y(Math.sin(angle),rise,Math.cos(angle)).normalize();
      detail("coal",new Eo(radius*.81,radius,length,8),along(x0,lift,z0,axis),1.64);
      for (const side of [-1,1]) {
        const d = side*length*.496, radiusEnd=radius*(side===1?.81:1);
        const tipX=x0+axis.x*d, tipY=lift+axis.y*d, tipZ=z0+axis.z*d;
        detail("bed",new Eo(radiusEnd*.80,radiusEnd*.90,.022,7),along(tipX,tipY,tipZ,axis),.85);
        detail("coal",new Eo(radiusEnd*.70,radiusEnd*.64,.024,7),along(tipX,tipY+.022,tipZ,axis),1.35);
      }
      const fissure=new Eo(radius*.74,radius*.75,length*.64,5);
      detail("bed",fissure,along(x0,lift-radius*.37,z0-.012,axis),.82);
    }
    for(let i=0;i<19;i++){
      const angle = i * 2.39996, r = .07 + Math.sqrt(i / 19) * .53;
      const x0 = Math.sin(angle) * r, z0 = Math.cos(angle) * r;
      const radius = .021 + .03 * grain(i,18);
      detail(i % 4 <= 1 ? "bed" : "coal",new kV(radius,5,3),E(x0,.751+grain(i,31)*.047,z0),1.24);
    }

    // The hearth apron joins the older, much larger funerary seal. Chips stay
    // flush to the walkable floor and break the edge of the new coal spill.
    for(let i=0;i<angles.length;i++){
      const a = angles[i], b = a+Math.PI/4, chip = (i%3)*.021;
      slab("seam",.746,1.172,a+.001,b-.001,.024,1.44);
      slab("ashlar",.759+chip*.3,1.155-chip*.32,a+.013,b-.013,.030,1.34+.16*grain(i,3));
      if (i!==2) slab("copper",1.092,1.108,a+.042,b-.053,.033,1.28+.17*grain(i,7));
      if (i%2===0) slab("gold",1.127,1.141,a+.29,b-.31,.034,1.12);
    }

    const newSurface = new h0();
    newSurface.setAttribute("position",new y0(new Float32Array(vertices),3));
    newSurface.setAttribute("uv",new y0(new Float32Array(UVs),2));
    newSurface.setAttribute("color",new y0(new Float32Array(swatches),3));
    newSurface.computeVertexNormals();
    const parts = groups.get(tileMaterial);
    parts.push(newSurface);
    const colors = new Float32Array(parts.reduce((sum,g)=>sum+g.getAttribute("color").array.length,0));
    let next=0;
    for(const g of parts){const a=g.getAttribute("color").array;colors.set(a,next);next+=a.length;}
    const geo = Z(BR(parts));
    geo.setAttribute("color",new y0(colors,3));
    const base = new pt(geo,tileMaterial);
    base.name = "hellArenaHearth";
    base.position.set(x,floor,z);
    scene.add(base);
    return base;
  }

  const phaseCount = 8, flameTileWidth = 42, flameTileHeight = 52;
  const flameAtlasWidth = phaseCount * flameTileWidth, flameAtlasHeight = 2 * flameTileHeight;
  function fireAtlas() {
    const atlas = Z(e0(ctx => {
      const pixels = ctx.createImageData(flameAtlasWidth,flameAtlasHeight);
      for (let kind = 0; kind < 2; kind++) for(let frame = 0; frame < phaseCount; frame++) {
        const time = frame / phaseCount * Math.PI * 2;
        for(let j=2;j<flameTileHeight-2;j++) for(let i=2;i<flameTileWidth-2;i++) {
          const h = (flameTileHeight - 3 - j) / (flameTileHeight - 5);
          const x = (i - (flameTileWidth - 1) / 2) / ((flameTileWidth - 5) * .5);
          let center = (.28 * Math.sin(h * 7.2 - .9 + .50*Math.sin(time)) + .108 * Math.cos(h * 17 - time)) * h;
          if (kind) center += .18 * Math.sin(h * 16 + time + 1.2) * h;
          const base = Math.sin(Math.min(1,h*11)*Math.PI/2);
          const breather = .87 + .125 * Math.sin(h * 21 + time * 2);
          const height = (kind ? .87 : 1) + .08 * Math.sin(time + kind);
          const above = Math.max(0,1-h/height);
          const width = breather * base * (.92 - .16 * kind) * Math.pow(above,.68);
          const edge = Math.abs(x-center) / Math.max(.045,width);
          const rough = .22*(grain(i,j,kind+3)-.5)+.23*(grain(i>>1,j>>1,frame%4)-.5);
          const shape = (1 - edge + rough) * base;
          if (shape < .07 || h > height || width < .048) continue;
          const stripe = .5 + .5*Math.sin(x*26 + h*43 + .8*Math.cos(time)+time+kind);
          const inner = clamp(shape + .20*stripe - .22*h + .14*(grain(i,j>>1,frame)-.5));
          // The hot core stays narrow and low. Rust-orange and smoke-dark red
          // survive into the tips so the pyre never burns as one yellow block.
          const ember = [.36,.15,.07], mid = [1,.405,.075], core = [1,.72,.25];
          const from = inner < .60 ? ember : mid, to = inner < .60 ? mid : core;
          const glow = inner < .60 ? inner / .60 : (inner - .60) / .40;
          const dst = ((kind*flameTileHeight+j)*flameAtlasWidth + frame*flameTileWidth + i)*4;
          for(let c=0;c<3;c++)pixels.data[dst+c] = (from[c] + (to[c]-from[c])*glow) * 255;
          pixels.data[dst+3]=clamp((shape-.02)*3.6) * 255;
        }
      }
      ctx.putImageData(pixels,0,0);
    },flameAtlasWidth,flameAtlasHeight));
    atlas.name="hellHearthFireCells";
    atlas.colorSpace=ha;
    return atlas;
  }

  function buildFire(base) {
    const surfaces = [];
    const material = Z(new $e({map:fireAtlas(),side:hi,alphaTest:.38,toneMapped:false}));
    const vertices = [], frames = [], triangle = [0,1,2,1,3,2];
    const tongues = [
      {x:-.01,z:-.021,y:.767,width:.89,height:1.28,yaw:.35,curve:.19,lean:.27,offset:0},
      {x:.31,z:-.149,y:.759,width:.48,height:.87,yaw:2.59,curve:.07,lean:.15,offset:3},
      {x:-.30,z:.02,y:.73,width:.56,height:1.13,yaw:2.04,curve:-.13,lean:-.18,offset:5},
      {x:.02,z:.26,y:.69,width:.54,height:.82,yaw:2.93,curve:-.10,lean:.09,offset:4},
    ];
    tongues.forEach((s,kind) => {
      const vertex = (u,v) => {
        const width=(u-.5)*s.width;
        const drift = s.curve*Math.sin(v*Math.PI) + s.lean*v*v;
        const curl = .15*v*v*Math.sin(s.yaw);
        vertices.push(s.x+Math.cos(s.yaw)*width+drift,s.y+v*s.height,
          s.z+Math.sin(s.yaw)*width+curl);
        frames.push(u,v,kind===0?0:1,s.offset);
      };
      for(let section=0;section<4;section++){
        const low=section/4, high=(section+1)/4;
        const points=[[0,low],[0,high],[1,low],[1,high]];
        triangle.forEach(index=>vertex(...points[index]));
      }
    });
    const geo = Z(new h0());
    geo.setAttribute("position",new y0(new Float32Array(vertices),3));
    const uv = new y0(new Float32Array(vertices.length / 3 * 2),2);
    geo.setAttribute("uv",uv);
    const flames = new pt(geo,material);
    flames.name="hellArenaHearthFlames";
    base.add(flames);
    surfaces.push(flames);

    function frame(index) {
      for (let i=0,j=0;i<frames.length;i+=4,j++) {
        const cell = (index + frames[i+3]) % phaseCount;
        uv.setXY(j,(cell*flameTileWidth + 1.5 + frames[i]*(flameTileWidth - 3))/flameAtlasWidth,
          1 - (frames[i+2]*flameTileHeight + 1.5 + (1-frames[i+1])*(flameTileHeight-3))/flameAtlasHeight);
      }
      uv.needsUpdate=true;
    }

    const spill = Z(e0((ctx,w,h)=>{
      const pixels = ctx.createImageData(w,h);
      for(let j=0;j<h;j++)for(let i=0;i<w;i++){
        const x=(i+.5-w/2)/(w/2),z=(j+.5-h/2)/(h/2);
        const r=Math.hypot(x*.98,z)+.045*(grain(i>>2,j>>2)-.5);
        const falloff=Math.pow(clamp(1-r),1.97);
        const shadows=.63+.37*Math.abs(Math.cos(Math.atan2(z,x)*3.96+.43));
        const n=(j*w+i)*4;
        pixels.data[n]=244; pixels.data[n+1]=114; pixels.data[n+2]=38;
        pixels.data[n+3]=falloff*shadows*(202+46*grain(i,j));
      }
      ctx.putImageData(pixels,0,0);
    },96,96));
    spill.name="hellHearthAmberSpill";
    spill.colorSpace=ha;
    const spillMaterial=Z(new $e({map:spill,transparent:true,depthWrite:false,blending:is,toneMapped:false}));
    const pool=new pt(Z(new Xe(6.06,5.44)),spillMaterial);
    pool.name="hellArenaHearthSpill";
    pool.rotation.x=-Math.PI/2;
    pool.position.y=.022;
    base.add(pool); surfaces.push(pool);
    frame(0);
    return {frame, spillMaterial, surfaces, age:0, phase:0};
  }

  let hearth = null;
  const buildDecor = FJ;
  FJ = function (scene, map) {
    buildDecor.apply(this,arguments);
    hearth = null;
    if (T.level !== 0 || !map.decor.some(spec => spec.k === "pyre" && isArenaPyre(spec))) return;
    const x = (pyreX + .5) * P, z = (pyreZ + .5) * P;
    const base=buildHearth(ie(x,z),scene,x,z);
    // The shared visual fire emitters serve all other braziers. Replace only
    // the loose bright particles at this one hearth with its compact flames.
    Gn.bowls=Gn.bowls.filter(emitter=>emitter.x!==x || emitter.z!==z);
    hearth=buildFire(base);
    hearth.x=x; hearth.z=z;
  };

  const updateDoors = F$;
  F$ = function (dt) {
    updateDoors.apply(this,arguments);
    if (!hearth || T.level !== 0 || Wk() || T.dead) return;
    const visible = (C.px - hearth.x)**2 + (C.pz - hearth.z)**2 < 34**2;
    for(const surface of hearth.surfaces)surface.visible=visible;
    if(!visible) return;
    hearth.age += dt;
    const phase = Math.floor(hearth.age * 10) % phaseCount;
    if (phase !== hearth.phase) {
      hearth.phase=phase;
      hearth.frame(phase);
    }
    hearth.spillMaterial.opacity=.83+.09*Math.sin(hearth.age*5.7)+.045*Math.sin(hearth.age*11.8+.3);
  };

  const crackle = utt.fireCrackle;
  utt.fireCrackle = function() {
    // Only spatialize the scheduled house sound when the pyre can be heard.
    // Reuse its interval and master routing, including focus, mute and pause.
    if (!hearth || T.level !== 0 || Math.hypot(C.px-hearth.x,C.pz-hearth.z) > 9) return crackle();
    return Nt(hearth.x,ie(hearth.x,hearth.z)+.82,hearth.z,crackle);
  };
})();
/* HELL_ARENA_HEARTH_END */
